                      'import sys\n'
                      'import pandas as pd\n'
                      '\n'
                      "customers_text, orders_text = sys.stdin.read().split('---\\n')\n"
                      'customers = pd.read_csv(io.StringIO(customers_text))\n'
                      'orders = pd.read_csv(io.StringIO(orders_text))\n'
                      "orders = orders[orders['customer_id'].isin(customers['id'])]\n"
                      "never = customers[~customers['id'].isin(orders['customer_id'])]['id'].sort_values()\n"
                      "print(' '.join(str(i) for i in never) if len(never) else 'NONE')\n"
                      "totals = orders.groupby('customer_id')['amount'].sum().reset_index()\n"
                      "totals = totals.sort_values(['amount', 'customer_id'], ascending=[False, True])\n"
